func Caesar(s string, n int) string {
	var result strings.Builder
	for _, r := range s {
		if isLetter(r) {
			offset := rune('a')
			if isUpper(r) {
				offset = rune('A')
			}
			result.WriteRune((r-offset+rune(n))%26 + offset)
		} else {
			result.WriteRune(r)
		}
	}
	return result.String()
}

func isLetter(r rune) bool {
	return (r >= 'a' && r <= 'z') || (r >= 'A' && r <= 'Z')
}

func isUpper(r rune) bool {
	return r >= 'A' && r <= 'Z'
}

