func Merge(a, b <-chan int) <-chan int {
    out := make(chan int)
    go func() {
        for a != nil || b != nil {
            select {
            case v, ok := <-a:
                if !ok {
                    a = nil
                } else {
                    out <- v
                }
            case v, ok := <-b:
                if !ok {
                    b = nil
                } else {
                    out <- v
                }
            }
        }
        close(out)
    }()
    return out
}

func main() {
    a := make(chan int)
    b := make(chan int)

    go func() {
        for i := 0; i < 5; i++ {
            a <- i
        }
        close(a)
    }()

    go func() {
        for i := 5; i < 10; i++ {
            b <- i
        }
        close(b)
    }()

    merged := Merge(a, b)

    for v := range merged {
        fmt.Println(v)
    }
}

