type Ring struct {
	items []int
	start int
	count int
	cap   int
}

func NewRing(cap int) *Ring {
	return &Ring{
		items: make([]int, cap),
		cap:   cap,
	}
}

func (r *Ring) Push(v int) {
	if r.count == r.cap {
		r.start = (r.start + 1) % r.cap
	} else {
		r.count++
	}
	r.items[(r.start+r.count-1)%r.cap] = v
}

func (r *Ring) Items() []int {
	result := make([]int, 0, r.count)
	for i := 0; i < r.count; i++ {
		result = append(result, r.items[(r.start+i)%r.cap])
	}
	return result
}

