func ParallelSum(nums []int, workers int) int {
	jobs := make(chan int)
	var wg sync.WaitGroup
	result := 0

	for i := 0; i < workers; i++ {
		wg.Add(1)
		go func() {
			defer wg.Done()
			for num := range jobs {
				result += num
			}
		}()
	}

	for _, num := range nums {
		jobs <- num
	}
	close(jobs)

	wg.Wait()
	return result
}

