// IntHeap implements heap.Interface for a min-heap of ints.
type IntHeap []int

func (h IntHeap) Len() int           { return len(h) }
func (h IntHeap) Less(i, j int) bool { return h[i] < h[j] }
func (h IntHeap) Swap(i, j int)      { h[i], h[j] = h[j], h[i] }

func (h *IntHeap) Push(x interface{}) {
	*h = append(*h, x.(int))
}

func (h *IntHeap) Pop() interface{} {
	old := *h
	n := len(old)
	x := old[n-1]
	*h = old[0 : n-1]
	return x
}

// PopAllSorted takes a slice of ints and returns them sorted in ascending order using a min-heap.
func PopAllSorted(vals []int) []int {
	h := &IntHeap{}
	heap.Init(h)
	for _, val := range vals {
		heap.Push(h, val)
	}
	sortedVals := make([]int, 0, len(vals))
	for h.Len() > 0 {
		sortedVals = append(sortedVals, heap.Pop(h).(int))
	}
	return sortedVals
}

