func ReadChunks(r io.Reader, size int) ([][]byte, error) {
	var chunks [][]byte
	buffer := make([]byte, size)
	for {
		n, err := r.Read(buffer)
		if n > 0 {
			chunks = append(chunks, buffer[:n])
		}
		if err == io.EOF {
			break
		}
		if err != nil {
			return nil, err
		}
	}
	return chunks, nil
}

